// Generated by python -m neoracer_spec.typescript from src/neoracer_spec. Do not edit.

export interface Source {
  readonly name: string; // short: "CAD", "docs", "firmware"
  readonly where: string; // enough to find it: a file, a page, a person and a date
}

/** Measured on the car or on its CAD model. */
export interface Measured {
  readonly kind: "Measured";
  readonly source: Source;
}

/** Fitted so that the car's own readings or commands agree with a reference: a scale factor of its odometry, the mounting angle of a sensor, the angle a steering command gives. */
export interface Calibrated {
  readonly kind: "Calibrated";
  readonly source: Source;
  readonly reference: string; // what it was fitted against: "the LiDAR", "a tape"
}

/** Read from a datasheet, the docs, the firmware or a config file. */
export interface Documented {
  readonly kind: "Documented";
  readonly source: Source;
}

/** Implied by a source but not stated by it. */
export interface Assumed {
  readonly kind: "Assumed";
  readonly source: Source;
  readonly why: string;
}

/** Nobody has measured it or read it anywhere. */
export interface Estimated {
  readonly kind: "Estimated";
  readonly why: string;
}

/** The model's own value, not a property of the car. */
export interface Chosen {
  readonly kind: "Chosen";
  readonly why: string;
}

export type Status = Measured | Calibrated | Documented | Assumed | Estimated | Chosen;

/** A value that another source gives. */
export interface Alternative<T> {
  readonly value: T;
  readonly source: Source;
}

export interface Sourced<T> {
  readonly value: T;
  readonly status: Status;
  // Why this value, when it needs saying.
  readonly note: string;
  // The values that other sources give. The spec is INCONSISTENT there.
  readonly conflicts: readonly Alternative<T>[];
}

export type Vec3 = readonly [number, number, number];

/** A body whose inertia is known, to scale to another of the same shape: its principal moments about its centre of mass, and its mass. */
export interface InertiaReference {
  readonly inertia: Vec3; // kg·m^2
  readonly mass: number; // kg
}

export interface Box {
  readonly center: Vec3; // m
  readonly half_size: Vec3; // m
}

export interface Chassis {
  readonly wheelbase: Sourced<number>; // m, between the front and rear axles
  readonly track: Sourced<number>; // m, between the left and right wheels' centres
  readonly mass: Sourced<number>; // kg, the whole car, wheels included
  readonly com_height: Sourced<number>; // m, the chassis' centre of mass above the axles
  readonly inertia: Sourced<InertiaReference>; // scaled to the chassis' mass
  readonly collision_box: Sourced<Box>; // the body less the wheels
}

export interface Wheel {
  readonly radius: Sourced<number>; // m, the tyre's
  readonly width: Sourced<number>; // m, the tyre's
  readonly mass: Sourced<number>; // kg, each
  readonly friction: Sourced<number>; // the tyre's sliding friction on the floor
  // Losses from the motor to the tyres, as damping on each wheel's spin.
  readonly drive_damping: Sourced<number>; // N·m·s/rad
}

export interface Suspension {
  readonly stiffness: Sourced<number>; // N/m, each wheel's spring
  readonly damping: Sourced<number>; // N·s/m, each wheel's damper
  readonly droop: Sourced<number>; // m, the wheel's travel down from rest
  readonly jounce: Sourced<number>; // m, the wheel's travel up from rest
}

export interface Battery {
  readonly voltage: Sourced<number>; // V
}

/** A DC motor's datasheet line: at voltage, its torque from rest and its speed with no load. */
export interface DcMotorRating {
  readonly voltage: number; // V
  readonly stall_torque: number; // N·m
  readonly free_speed_rpm: number; // rpm
}

export interface DriveMotor {
  readonly rating: Sourced<DcMotorRating>;
  readonly gear_ratio: Sourced<number>; // motor turns per wheel turn
}

export interface Esc {
  // What the motor does at neutral throttle: short its windings (brake) or
  // leave them open (coast).
  readonly neutral: Sourced<"brake" | "coast">;
}

/** A hobby servo's datasheet line, in the units it is rated in. */
export interface ServoRating {
  readonly voltage: number; // V
  readonly stall_torque_kgf_cm: number; // kgf·cm
  readonly seconds_per_60_degrees: number; // s, with no load
}

/** Steps between the centre and the driver's full lock, the car at rest on the floor, each timed from the command written to the car's board: when the chassis first moves, and when each swing ends. */
export interface ServoSteps {
  readonly first_motion: number; // s
  readonly centre_to_lock: number; // s
  readonly lock_to_lock: number; // s
  readonly lock_to_centre: number; // s
}

export interface SteeringServo {
  // Two datasheet lines; the rating at supply is interpolated between them.
  readonly low: Sourced<ServoRating>;
  readonly high: Sourced<ServoRating>;
  readonly supply: Sourced<number>; // V
  // How far the horn turns from the centre over the firmware's pulse range.
  readonly horn_half_range_degrees: Sourced<number>;
  // The servo's own position loop, the model's.
  readonly kp: Sourced<number>; // V/rad
  readonly kd: Sourced<number>; // V·s/rad
  // How long a command takes from the car's board to the servo's loop: the
  // firmware's control loop and pulse, and the servo's own dead time.
  readonly latency: Sourced<number>; // s
  // The car's steering steps at rest, which latency is fitted to.
  readonly steps_at_rest: Sourced<ServoSteps>;
}

export interface Steering {
  // The inner front wheel's angle at full lock.
  readonly inner_lock_degrees: Sourced<number>;
  // The share of the horn's half range that the car's driver commands at
  // full lock.
  readonly driver_lock: Sourced<number>;
  // The steering input's range (rad): the model's Ackermann constraints fit
  // over it, so it must be wider than full lock.
  readonly fit_range: Sourced<number>;
  // How far (rad) past the inner wheel's angle at fit_range the front
  // wheels' steer joints reach, so their limits never oppose the
  // constraints.
  readonly wheel_range_margin: Sourced<number>;
  // The model's virtual body that the steering input turns, between the
  // servo and the Ackermann constraints. Its mass comes off the chassis'.
  readonly input_body_mass: Sourced<number>; // kg
  // Inertia added at the steering input and at each front wheel's steer
  // joint: the servo's rotor, seen through its gears, turns with them.
  readonly armature: Sourced<number>; // kg·m²
}

/** The firmware's speed loop: a PID on the encoder's speed, with a feed-forward, driving the ESC's pulse. */
export interface SpeedController {
  readonly period: Sourced<number>; // s
  readonly kp: Sourced<number>; // us of pulse per m/s of error
  readonly ki: Sourced<number>;
  readonly kd: Sourced<number>;
  readonly speed_filter_weight: Sourced<number>; // of the new speed in the loop's low-pass
  readonly feed_forward: Sourced<number>; // us of pulse per m/s commanded
  readonly deadband: Sourced<number>; // us, the smallest pulse past neutral that it sends
  readonly full_pulse: Sourced<number>; // us past neutral, full throttle
  readonly max_speed: Sourced<number>; // m/s
}

export interface MotorEncoder {
  readonly pulses_per_turn: Sourced<number>; // a turn of the motor
  readonly max_speed_rpm: Sourced<number>; // rpm, its rating
  // Every report_period the firmware turns the count over the period into
  // the tyre's surface speed and low-pass filters it with filter_weight on
  // the new period.
  readonly report_period: Sourced<number>; // s
  readonly filter_weight: Sourced<number>;
}

export interface Imu {
  readonly position: Sourced<Vec3>; // m
  readonly rate: Sourced<number>; // Hz, of the readings the car publishes
  readonly accel_range_g: Sourced<number>; // g, the accelerometer's full scale
  readonly gyro_range_dps: Sourced<number>; // degrees/s, the gyroscope's full scale
  readonly magnetometer_range_gauss: Sourced<number>; // gauss
}

export interface Lidar {
  readonly position: Sourced<Vec3>; // m, the centre of the scan
  readonly scan_rate: Sourced<number>; // Hz, turns a second
  readonly resolution_degrees: Sourced<number>; // between two samples
  readonly field_degrees: Sourced<number>; // of bearings it sees, centered on the front
  readonly range_bright: Sourced<number>; // m at least, on a target of 90% reflectivity
  readonly range_dark: Sourced<number>; // m at least, on a target of 10% reflectivity
  readonly accuracy: Sourced<number>; // m
}

export interface Resolution {
  readonly width: number; // pixels
  readonly height: number; // pixels
  readonly fps: number; // Hz
}

export interface Camera {
  readonly position: Sourced<Vec3>; // m, the lens
  readonly sensor: Sourced<Resolution>; // the sensor's most
  readonly fov_degrees: Sourced<number>;
  readonly focal_length: Sourced<number>; // m
  readonly shutter: Sourced<"global" | "rolling">;
  readonly stream: Sourced<Resolution>; // what the car's driver asks for
}

export interface Visuals {
  // The wheels' radius in the cosmetic wheel meshes, which are scaled to the
  // tyre.
  readonly mesh_wheel_radius: Sourced<number>; // m
}

export interface Spec {
  readonly chassis: Chassis;
  readonly wheel: Wheel;
  readonly suspension: Suspension;
  readonly battery: Battery;
  readonly motor: DriveMotor;
  readonly esc: Esc;
  readonly servo: SteeringServo;
  readonly steering: Steering;
  readonly speed_controller: SpeedController;
  readonly encoder: MotorEncoder;
  readonly imu: Imu;
  readonly lidar: Lidar;
  readonly camera: Camera;
  readonly visuals: Visuals;
}

export type Nominal = readonly [number, number, number];

export interface DcMotorParams {
  readonly nominal: Nominal; // at the shaft
  readonly gear: number; // shaft turns per turn of what it drives
  readonly ctrl_limit: number; // V, |ctrl| at most
}

export interface ServoParams {
  readonly nominal: Nominal; // at the steering input, through the linkage
  readonly kp: number; // V/rad
  readonly kd: number; // V·s/rad
  readonly voltage_limit: number; // V, the loop's clamp
  readonly lock: number; // rad of steering input, |ctrl| at most
  readonly latency: number; // s
  readonly nsample: number;
}

export type Polynomial = readonly [number, number, number, number, number];

/** The car model's numbers. Positions are in the car's body frame. */
export interface ModelParams {
  readonly spawn_height: number; // m, of the body frame above the floor
  readonly chassis_mass: number; // kg
  readonly chassis_inertia: Vec3; // kg·m^2
  readonly com_height: number; // m
  readonly box_center: Vec3; // m, the chassis' collision box
  readonly box_half_size: Vec3; // m
  readonly imu_position: Vec3; // m
  readonly lidar_position: Vec3; // m
  readonly lidar_scan_rate: number; // Hz, turns of its head a second
  readonly lidar_field: number; // rad of bearings it sees, centred on the front
  readonly half_wheelbase: number; // m
  readonly half_track: number; // m
  readonly wheel_radius: number; // m
  readonly tyre_half_width: number; // m
  readonly wheel_mass: number; // kg
  readonly wheel_friction: number;
  readonly wheel_damping: number; // N·m·s/rad
  readonly wheel_mesh_scale: number;
  readonly input_body_mass: number; // kg
  readonly spring_stiffness: number; // N/m
  readonly spring_damping: number; // N·s/m
  readonly spring_ref: number; // m, the spring's rest position
  readonly droop: number; // m
  readonly jounce: number; // m
  readonly steer_input_range: number; // rad
  readonly wheel_steer_range: number; // rad
  readonly steer_armature: number; // kg·m²
  readonly motor: DcMotorParams;
  readonly servo: ServoParams;
  readonly ackermann_left: Polynomial; // the left wheel's angle from the steering input
}

/** The LiDAR's scan. The defaults are the NeoRacer's: lidar_params(NEORACER.lidar). */
export interface LidarParams {
  readonly slots: number; // slots a turn
  readonly scan_rate: number; // Hz, turns a second
  readonly max_range: number; // m, its range on a bright target
  // rad of bearings it sees, centered on the front
  readonly field: number;
}

/** How the firmware measures the speed from the motor encoder. The defaults are the NeoRacer's: encoder_params(NEORACER.encoder). */
export interface EncoderParams {
  readonly window: number; // s, the firmware's control period
  readonly alpha: number; // the weight of the new window in the filter
}

/** Everything the simulators need, derived from a Spec. */
export interface DerivedParams {
  readonly model: ModelParams;
  readonly lidar: LidarParams;
  readonly encoder: EncoderParams;
  readonly wheel_radius: number; // m, that the encoder's speed is measured at
  readonly steer_lock: number; // rad of steering input, full lock
}

